script:
frappe.ui.form.on("Purchase Expenses", {
  setup(frm) {
    frm.set_query("account", function () {
      return {
        filters: {
          account_type: ["in", ["Bank", "Cash"]],
          is_group: 0,
          company: frm.doc.company
        }
      };
    });
  }
});

frappe.ui.form.on('Purchase Expenses', {
    // nothing needed here for now
});

// handle child table events
frappe.ui.form.on('Purchase Expenses Item', {
    item_name: function(frm, cdt, cdn) {
        let row = locals[cdt][cdn];
        if(row.item_name) {
            frappe.call({
                method: "frappe.client.get_value",
                args: {
                    doctype: "Item",
                    filters: { name: row.item_name },
                    fieldname: ["standard_rate"]
                },
                callback: function(r) {
                    if(r.message) {
                        row.rate = r.message.standard_rate;
                        row.total = row.rate * (row.qty || 0);
                        frm.refresh_field("items"); // child table fieldname in parent
                    }
                }
            });
        }
    },

    qty: function(frm, cdt, cdn) {
        let row = locals[cdt][cdn];
        row.total = row.rate * (row.qty || 0);
        frm.refresh_field("items");
    },

    rate: function(frm, cdt, cdn) {
        let row = locals[cdt][cdn];
        row.total = row.rate * (row.qty || 0);
        frm.refresh_field("items");
    }
});
